queries.sphinxql:
insert into tb values (3011, 'doc rare', 'rare', ());
flush ramchunk tb;


select id, knn_dist() d from tb where category='rare' and knn(vec, 5, (0,0,0,0)) order by d asc; show meta like 'index';


select id, knn_dist() d from tb where category='rare' and knn(vec, 5, (0,0,0,0), {fullscan=1}) order by d asc; show meta like 'index';


select id from tb where id=3011 and category='rare' and knn(vec, 5, (0,0,0,0));


select id, knn_dist() d from tb where match('rare') and category='rare' and knn(vec, 5, (0,0,0,0)) order by d asc;


select id, knn_dist() d from tb where knn(vec, 3, (0,0,0,0)) order by d asc; show meta like 'index';
drop table tb;

create table ts (title text, category int, vec float_vector knn_type='hnsw' knn_dims='4' hnsw_similarity='l2');
